const KEY="vuralpt_v16";
const OLD_KEY="vuralpt_v15";
const seed={
 A:{id:"A",name:"A Antrenmanı",focus:"Göğüs + Kollar",exerciseIds:["chest_press","incline_db_press","pec_deck","triceps_pushdown","biceps_curl","ab_crunch"]},
 B:{id:"B",name:"B Antrenmanı",focus:"Sırt + Omuz",exerciseIds:["lat_pulldown","cable_row","shoulder_press","lateral_raise","face_pull","dead_bug"]}
};
let S=load(), builder=[], builderConfig={}, current=null, restTimer=null, restLeft=0;
migrateV2();
function load(){try{let x=JSON.parse(localStorage.getItem(KEY));if(x)return x;let old=JSON.parse(localStorage.getItem(OLD_KEY));if(old){localStorage.setItem(KEY,JSON.stringify(old));return old}return {history:[],programs:{},weights:{},cycles:{},last:null,lastRecommended:null,recommendationIds:["A","B"]}}catch(e){return {history:[],programs:{},weights:{},cycles:{},last:null,lastRecommended:null,recommendationIds:["A","B"]}}}
function save(){localStorage.setItem(KEY,JSON.stringify(S))}
function weightState(id){
  if(!S.progression) S.progression={};
  if(!S.progression[id]) S.progression[id]={weight:S.weights[id]??10,successful:0,pending:false};
  return S.progression[id];
}
function recordSuccessfulExposure(id, weight){
  const st=weightState(id);
  const w=Number(weight);
  if(Number.isFinite(w)&&w>=0){
    if(st.weight!==w){st.weight=w;st.successful=0;st.pending=false}
    st.successful=Math.min(10,st.successful+1);
    if(st.successful>=10) st.pending=true;
  }
}
function acknowledgeIncrease(id,newWeight){
  const st=weightState(id);
  st.weight=Number(newWeight);
  st.successful=0;
  st.pending=false;
  S.weights[id]=Number(newWeight);
  save();
}
function progressionNotice(id){
  const st=weightState(id);
  if(!st.pending)return "";
  return `<div class="increase"><b>Ağırlık artırma zamanı</b><span>${esc(ex(id).name)} hareketini ${st.weight} kg ile 10 başarılı antrenman döngüsünde tamamladın. Sonraki döngüde ağırlığı artır.</span><div class="increaseRow"><input id="increaseWeight" type="number" step=".5" value="${Number(st.weight)+2}"><button onclick="applyIncrease('${id}')">UYGULA</button></div></div>`;
}
function applyIncrease(id){
  const v=Number(document.getElementById("increaseWeight")?.value);
  if(!Number.isFinite(v)||v<=0)return;
  acknowledgeIncrease(id,v);
  exerciseView();
}

