function ex(id){return LIBRARY.find(x=>x.id===id)}
function programs(){return [seed.A,seed.B,...Object.values(S.programs)]}
function prog(id){return programs().find(x=>x.id===id)}
function nextId(){let ids=Object.keys(S.programs);let n=67;while(S.programs[String.fromCharCode(n)])n++;return String.fromCharCode(n)}
function cyclePrograms(){
  const ids=Array.isArray(S.recommendationIds)&&S.recommendationIds.length?S.recommendationIds:["A","B"];
  return ids.map(id=>prog(id)).filter(Boolean);
}
function nextProgram(){
  const p=cyclePrograms();
  if(!p.length) return seed.A;
  const last=S.lastRecommended||null;
  if(!last) return p[0];
  const i=p.findIndex(x=>x.id===last);
  return p[i<0?0:(i+1)%p.length]||p[0];
}
function cycleInfo(){
  const p=cyclePrograms(), next=nextProgram();
  return {count:p.length, last:S.lastRecommended||null, next:next?.id||null,
          sequence:p.map(x=>x.id)};
}
function recommendationChecked(id){return (S.recommendationIds||[]).includes(id)}
function toggleRecommendation(id,checked){
  let ids=[...(S.recommendationIds||[])];
  if(checked){if(!ids.includes(id))ids.push(id)}else{ids=ids.filter(x=>x!==id)}
  if(!ids.length){alert("En az bir antrenman önerilen döngüde olmalı.");home();return}
  S.recommendationIds=ids;
  if(!ids.includes(S.lastRecommended))S.lastRecommended=null;
  save();home();
}
function totalEstimatedCalories(){
  return Math.round((S.history||[]).reduce((sum,h)=>sum+(Math.max(0,Number(h.duration)||0)/60000)*5,0));
}
function fmt(d){return new Intl.DateTimeFormat("tr-TR",{day:"2-digit",month:"long",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(d))}
function date(d){return new Intl.DateTimeFormat("tr-TR",{day:"2-digit",month:"2-digit",year:"numeric"}).format(new Date(d))}
function dur(ms){let m=Math.round(ms/60000);return m+" dk"}
function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
function nav(id){["navHome","navWorkout","navHistory","navAnalysis"].forEach(x=>document.getElementById(x)?.classList.toggle("active",x===id))}
const screen=document.getElementById("appScreen");
function photo(e){let n=THUMBNAILS[e.id];let src=`assets/detail-images/detail_${String(n).padStart(2,"0")}.jpg`;return `<div class="photo vignette"><img src="${esc(src)}" alt="${esc(e.name)}" loading="eager" onerror="this.style.display='none';this.nextElementSibling.style.display='block'"><span>Görsel yüklenemedi</span></div>`}
function thumbPhoto(e){let n=THUMBNAILS[e.id];let src=`assets/thumbs/sprite_${String(n).padStart(2,"0")}.jpg`;return `<div class="libThumb"><img src="${esc(src)}" alt="${esc(e.name)}" loading="lazy" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><span>Görsel</span></div>`}

