function home(){
 nav("navHome");
 let p=nextProgram(),last=S.history.at(-1),cal=totalEstimatedCalories(),cycle=cyclePrograms();
 screen.innerHTML=`
<section class="hero homeHero">
 <div class="eyebrow">BUGÜN</div>
 <div class="suggest">● Önerilen: <b>${esc(p.name)}</b></div>
 <h1>${esc(p.name.replace(" Antrenmanı",""))}</h1>
 <p>${esc(p.focus)}</p>
 <div class="actions"><button class="primary" onclick="start('${p.id}')">ÖNERİLENİ BAŞLAT</button><button class="secondary" onclick="picker()">ANTRENMAN SEÇ</button></div>
 <div class="cycleStatus">Öneri döngüsü: <b>${cycle.map(x=>esc(x.id)).join(" → ")}</b></div>
</section>
<section class="homeMotto"><div class="motto">NO PAIN,<br><strong>NO GAIN.</strong></div><span>Disiplin, tekrar ve istikrar.</span></section>
<div class="grid2"><div class="metric"><span>Son antrenman</span><b>${last?esc(prog(last.type)?.name||last.type):"—"}</b><small>${last?date(last.date):"Henüz kayıt yok"}</small></div><div class="metric"><span>Tahmini toplam kalori</span><b>${cal.toLocaleString("tr-TR")} kcal</b><small>tamamlanan antrenmanlardan</small></div></div>
<section class="card recommendationCard"><div class="eyebrow">ÖNERİLEN ANTRENMAN DÖNGÜSÜ</div><h3>Hangi antrenmanlar sıraya girsin?</h3><p>Aşağıdan seç. Sistem yalnızca işaretlediklerini döngüye dahil eder; kendi programını da istersen ekleyebilirsin.</p>
<div class="recommendationChecks">${[seed.A,seed.B,...Object.values(S.programs)].map(x=>`<label><input type="checkbox" ${recommendationChecked(x.id)?"checked":""} onchange="toggleRecommendation('${x.id}',this.checked)"><span><b>${esc(x.id)}</b><small>${esc(x.name)}</small></span></label>`).join("")}</div></section>`
}
function picker(){nav("navWorkout");let p=nextProgram(), customs=Object.values(S.programs);screen.innerHTML=`
<div class="head"><button class="back" onclick="home()">← Ana sayfa</button><div class="eyebrow">ANTRENMAN SEÇ</div><h1>Bugün ne yapmalıyım?</h1><p>Önerilen programı başlatabilir veya başka bir program seçebilirsin.</p></div>
<button class="choice recommended" onclick="start('${p.id}')"><label>ÖNERİLEN</label><b>${esc(p.name)}</b><span>${esc(p.focus)}</span><i>→</i></button>
<div class="section">HAZIR PROGRAMLAR</div>${[seed.A,seed.B].map(choice).join("")}
${customs.length?'<div class="section">KENDİ ANTRENMANLARIM</div>':""}${customs.map(x=>choice(x,true)).join("")}
<button class="create" onclick="builderView()">＋ Yeni antrenman oluştur</button>`}
function choice(p,custom){return `<button class="choice" onclick="start('${p.id}')"><b>${esc(p.name)}</b><span>${esc(p.focus)} · ${p.exerciseIds.length} hareket</span><i>→</i></button>${custom?`<button class="edit" onclick="event.stopPropagation();builderView('${p.id}')">Düzenle</button>`:""}`}

function builderView(id){
 let p=id?S.programs[id]:null;builder=p?[...p.exerciseIds]:[];builderConfig=p?.exerciseConfig?{...p.exerciseConfig}:{};let code=p?.id||nextId();window.builderName=p?.name||"";window.builderCode=code;
 screen.innerHTML=`<div class="head"><button class="back" onclick="picker()">← Antrenman seç</button><div class="eyebrow">ANTRENMAN OLUŞTUR</div><h1>${code}</h1><p>En fazla 8 hareket. Önce sağlık, sonra ilerleme.</p></div>
<label class="field">Antrenman adı<input id="pname" value="${esc(p?.name||"")}" placeholder="Örn. Göğüs + Omuz"></label>
<div class="builderHead"><b>Hareketler</b><strong id="count">${builder.length} / 8</strong></div><div id="healthHint">${healthCheck(builder)}</div><div id="rows">${rows()}</div>
<button class="add" onclick="libraryView('${code}')">＋ HAREKET EKLE</button><button class="primary wide" onclick="saveProgram('${code}')">ANTRENMANI OLUŞTUR</button>`
}
function configureBuilderExercise(id){
 let e=ex(id), p=builderConfig?.[id]||{sets:e.sets,reps:e.reps,weight:S.weights[id]??10};
 screen.innerHTML=`<div class="head"><button class="back" onclick="builderView('${window.builderCode}')">← Antrenmanı düzenle</button><div class="eyebrow">HAREKET AYARI</div><h1>${esc(e.name)}</h1></div>${photo(e)}
 <div class="configGrid"><label>Set<input id="cfgSets" type="number" min="1" max="6" value="${p.sets}"></label><label>Tekrar<input id="cfgReps" value="${esc(p.reps)}"></label><label>Ağırlık<input id="cfgWeight" type="number" step=".5" value="${p.weight}"> kg</label></div>
 <button class="primary wide" onclick="saveBuilderExercise('${id}')">KAYDET</button>`;
}
function saveBuilderExercise(id){
 if(!window.builderConfig)window.builderConfig={};
 builderConfig[id]={sets:Math.max(1,Math.min(6,Number(document.getElementById("cfgSets").value)||3)),reps:document.getElementById("cfgReps").value.trim()||"10–12",weight:Number(document.getElementById("cfgWeight").value)||10};
 builderView(window.builderCode);
}
function rows(){return builder.map((id,i)=>{let e=ex(id),c=builderConfig[id]||{sets:e.sets,reps:e.reps};return `<div class="row"><em>${i+1}</em><div><b>${esc(e.name)}</b><small>${esc(e.primary)} · ${c.sets} set · ${esc(c.reps)}</small></div><button onclick="configureBuilderExercise('${id}')">⚙</button><button onclick="removeEx('${id}')">×</button></div>`}).join("")||`<div class="emptyMini">Henüz hareket seçilmedi.</div>`}
function removeEx(id){builder=builder.filter(x=>x!==id);document.getElementById("rows").innerHTML=rows();document.getElementById("count").textContent=`${builder.length} / 8`}
function libraryView(code){let nameInput=document.getElementById("pname");if(nameInput)window.builderName=nameInput.value.trim();screen.innerHTML=`<div class="head"><button class="back" onclick="builderView('${code}')">← Antrenmanı düzenle</button><div class="eyebrow">HAREKET KÜTÜPHANESİ</div><h1>Hareket seç</h1><p>${builder.length} / 8 seçili</p></div>
<div id="selectedWrap"></div><input id="q" class="search" placeholder="🔍 Hareket ara..." oninput="renderLibrary()"><div class="filters">${["Tümü","Göğüs","Sırt","Omuz","Biceps","Triceps","Bacak","Karın","Core","Conditioning"].map(x=>`<button onclick="filterLib='${x}';renderLibrary()">${x}</button>`).join("")}</div><div id="lib"></div>`;window.filterLib="Tümü";window.builderCode=code;renderLibrary()}
function renderLibrary(){
 let q=(document.getElementById("q")?.value||"").toLowerCase(),f=window.filterLib||"Tümü";
 let a=LIBRARY.filter(e=>(f==="Tümü"||e.primary.includes(f)||f==="Bacak"&&["Quadriceps","Hamstring","Glute","Calf"].some(x=>e.primary.includes(x)))&&(!q||(`${e.name} ${e.primary} ${e.equipment}`).toLowerCase().includes(q)));
 const card=e=>`<button class="libCard ${builder.includes(e.id)?"selectedLibCard":""}" onclick="detail('${e.id}')">${thumbPhoto(e)}<div class="libInfo"><b>${esc(e.name)}</b><small>${esc(e.primary)} · ${esc(e.equipment)}</small><small>${esc(e.level)} · ${esc(e.reps)} · ${e.sets} set</small></div><strong>${builder.includes(e.id)?"✓":"＋"}</strong></button>`;
 const selected=builder.map(ex).filter(Boolean);
 document.getElementById("selectedWrap").innerHTML=selected.length?`<section class="selectedExercises"><div class="section">SEÇİLEN HAREKETLER <span>${selected.length}/8</span></div>${selected.map(card).join("")}<button class="primary wide selectedSave" onclick="saveProgram(window.builderCode)">ANTRENMANI KAYDET</button></section>`:"";
 document.getElementById("lib").innerHTML=a.map(card).join("");
}
function detail(id){let e=ex(id),chosen=builder.includes(id);screen.innerHTML=`<div class="head"><button class="back" onclick="libraryView('${window.builderCode}')">← Kütüphane</button></div><section class="card detail">${photo(e)}<h1>${esc(e.name)}</h1><div class="tags"><span>${esc(e.primary)}</span><span>${esc(e.equipment)}</span><span>${esc(e.level)}</span></div><h3>Nasıl yapılır?</h3><p>${esc(e.how)}</p><h3>Dikkat</h3><p>${esc(e.attention)}</p><div class="suggested"><b>Önerilen başlangıç</b><span>${e.sets} set · ${esc(e.reps)} · ${e.rest} sn dinlenme</span></div><button class="secondary wide" onclick="toggleFavorite('${e.id}')">${(S.favorites||[]).includes(e.id)?"★ FAVORİLERDEN ÇIKAR":"☆ FAVORİLERE EKLE"}</button><button class="primary wide" onclick="toggle('${e.id}')">${chosen?"ÇIKAR":"ANTRENMANA EKLE"}</button></section>`}
function toggle(id){if(builder.includes(id))builder=builder.filter(x=>x!==id);else{if(builder.length>=8){return}builder.push(id)}libraryView(window.builderCode)}
function healthGate(){screen.innerHTML=`<section class="health"><div class="healthIcon">+</div><div class="eyebrow">ÖNCE SAĞLIK</div><h1>8 hareket seçtin.</h1><p>VuralPT, tek antrenmanda en fazla 8 hareketi <b>uygulama sınırı</b> olarak kullanır. Bu sayı tıbbi bir güvenlik eşiği değildir.</p><div class="healthBox"><b>Devam etmeden önce</b><span>Seçtiğin hareketlerin gerçekten gerekli olduğunu ve toplam hacmin sana uygun olduğunu gözden geçir.</span><span>Ağrı, baş dönmesi, olağandışı nefes darlığı veya kendini kötü hissetme durumunda egzersizi bırak.</span></div><button class="primary wide" onclick="builderView('${window.builderCode}')">SEÇİMLERİ GÖZDEN GEÇİR</button><button class="secondary wide" onclick="builderView('${window.builderCode}')">DEVAM ET</button></section>`}
function saveProgram(code){let input=document.getElementById("pname");let name=(input?.value||window.builderName||"").trim()||`${code} Antrenmanı`;if(!builder.length){alert("En az 1 hareket seç.");return}window.builderName=name;S.programs[code]={id:code,name,focus:builder.map(x=>ex(x).primary).slice(0,4).join(" + "),exerciseIds:[...builder],exerciseConfig:{...builderConfig}};save();picker()}

function start(type){let p=prog(type);current={type,index:0,start:Date.now(),session:[],reps:[]};exerciseView()}
function exerciseView(){clearInterval(restTimer);let p=prog(current.type),list=p.exerciseIds.map(ex),e=list[current.index],w=S.weights[e.id]??(e.equipment==="Vücut ağırlığı"?0:10);screen.innerHTML=`<div class="workTop"><div><div class="eyebrow">${esc(p.name)}</div><b>Hareket ${current.index+1} / ${list.length}</b></div><strong>${current.index+1}/${list.length}</strong></div><div class="progress"><i style="width:${(current.index+1)/list.length*100}%"></i></div>
<section class="card workoutCard">${photo(e)}<div class="titleRow"><div><h1>${esc(e.name)}</h1><p>${esc(e.primary)}</p></div><span class="cycle">${S.cycles[e.id]||0}/10</span></div><div class="meta"><span>${e.sets} set</span><span>${esc(e.reps)} tekrar</span><span>${e.rest} sn</span></div>${progressionNotice(e.id)}
<label class="weight">Ağırlık<div><input id="weight" type="number" step=".5" value="${w}" ${e.equipment==="Vücut ağırlığı"?"disabled":""}><b>${e.equipment==="Vücut ağırlığı"?"—":"kg"}</b></div></label>
<button class="saveWeight" onclick="saveW('${e.id}')">✓ Ağırlığı kaydet</button><details><summary>Hareketi nasıl yapmalıyım?</summary><p>${esc(e.how)}</p></details>
<div class="setsHead"><b>Setler</b><span>Hedef ${esc(e.reps)}</span></div><div class="sets">${Array.from({length:e.sets},(_,i)=>`<div class="set"><em>${i+1}</em><input id="rep${i}" type="number" inputmode="numeric" placeholder="${esc(e.reps)}"><button onclick="setDone(${i})">✓</button></div>`).join("")}</div>
<button class="restBtn" onclick="rest(${e.rest})">⏱ Dinlenme başlat · ${e.rest} sn</button><div id="rest"></div><button class="next" onclick="nextMove()">${current.index===list.length-1?"✓ ANTRENMANI BİTİR":"SONRAKİ HAREKET →"}</button></section>`}
function saveW(id){let v=Number(document.getElementById("weight").value);if(Number.isFinite(v)&&v>=0){let st=weightState(id);st.weight=v;st.successful=0;st.pending=false;S.weights[id]=v;save();document.querySelector(".saveWeight").textContent="✓ Kaydedildi"}}
function setDone(i){let v=Number(document.getElementById("rep"+i).value);if(!v){alert("Önce tekrar sayısını gir.");return}current.reps[i]=v;let e=prog(current.type).exerciseIds.map(ex)[current.index];saveW(e.id);if(i<e.sets-1)rest(e.rest)}
function rest(sec){clearInterval(restTimer);restLeft=sec;let box=document.getElementById("rest");if(!box)return;box.className="restBar";box.innerHTML=`<span>Dinlenme <b id="rt"></b></span><button onclick="skipRest()">Atla</button>`;tick();restTimer=setInterval(()=>{restLeft--;tick();if(restLeft<=0){clearInterval(restTimer);navigator.vibrate?.(150)}},1000)}
function tick(){let x=document.getElementById("rt");if(x)x.textContent=`${String(Math.floor(restLeft/60)).padStart(2,"0")}:${String(restLeft%60).padStart(2,"0")}`}
function skipRest(){clearInterval(restTimer);document.getElementById("rest")?.classList.add("hidden")}
function nextMove(){let p=prog(current.type),e=p.exerciseIds.map(ex)[current.index],reps=current.reps.slice();if(reps.length<e.sets&&!confirm("Tüm setler tamamlanmadı. Devam edilsin mi?"))return;let ok=reps.length===e.sets;current.session.push({id:e.id,reps,weight:S.weights[e.id]??weightState(e.id).weight??0,success:ok});
if(ok && e.equipment!=="Vücut ağırlığı") recordSuccessfulExposure(e.id,S.weights[e.id]??weightState(e.id).weight);if(current.index<p.exerciseIds.length-1){current.index++;current.reps=[];exerciseView()}else finish()}
function finish(){let record={date:new Date().toISOString(),type:current.type,duration:Date.now()-current.start,exercises:current.session};S.history.push(record);S.last=current.type;if((S.recommendationIds||[]).includes(current.type))S.lastRecommended=current.type;record.exercises.forEach(x=>{if(x.success)S.cycles[x.id]=Math.min(10,(S.cycles[x.id]||0)+1)});save();let inc=record.exercises.filter(x=>S.cycles[x.id]>=10).map(x=>ex(x.id).name);screen.innerHTML=`<section class="finish"><div class="finishIcon">✓</div><div class="eyebrow">ANTRENMAN KAYDEDİLDİ</div><h1>${esc(prog(record.type).name)}</h1><p>${fmt(record.date)} · ${dur(record.duration)}</p>${inc.length?`<div class="increase"><b>Ağırlık artırma zamanı</b><span>${inc.map(esc).join("<br>")}</span></div>`:""}<button class="primary wide" onclick="home()">ANA SAYFAYA DÖN</button><button class="secondary wide" onclick="historyView()">KAYDI GÖR</button></section>`}

function historyView(){nav("navHistory");let h=S.history;if(!h.length){screen.innerHTML=`<div class="head"><div class="eyebrow">GEÇMİŞ</div><h1>Antrenman Günlüğü</h1></div><div class="empty"><h2>Henüz kayıt yok</h2><p>İlk antrenmanını tamamladığında kayıt burada görünecek.</p></div>`;return}
let last=h.at(-1);screen.innerHTML=`<div class="head"><div class="eyebrow">GEÇMİŞ</div><h1>Antrenman Günlüğü</h1><p>Yalnızca gerçekten tamamlanan antrenmanlar kaydedilir.</p></div><div class="last"><span>SON ANTRENMAN</span><b>${esc(prog(last.type).name)}</b><small>${fmt(last.date)} · ${dur(last.duration)}</small></div><div>${[...h].reverse().map((x,i)=>`<button class="log" onclick="logDetail(${h.length-1-i})"><div><b>${esc(prog(x.type).name)}</b><small>${fmt(x.date)}</small></div><strong>${dur(x.duration)}<small>${x.exercises.length} hareket →</small></strong></button>`).join("")}</div><button class="danger" onclick="clearHistory()">TÜM KAYITLARI SİL</button>`}
function logDetail(i){let h=S.history[i];screen.innerHTML=`<div class="head"><button class="back" onclick="historyView()">← Geçmiş</button><div class="eyebrow">ANTRENMAN DETAYI</div><h1>${esc(prog(h.type).name)}</h1><p>${fmt(h.date)} · ${dur(h.duration)}</p></div>${h.exercises.map(x=>`<div class="logDetail"><div><b>${esc(ex(x.id).name)}</b><span>${x.weight?x.weight+" kg":"Vücut ağırlığı"}</span></div><small>${x.reps.map((r,i)=>`Set ${i+1}: ${r}`).join(" · ")}</small></div>`).join("")}<button class="danger" onclick="deleteLog(${i})">BU KAYDI SİL</button>`}
function deleteLog(i){if(confirm("Bu kayıt silinsin mi?")){S.history.splice(i,1);S.last=S.history.at(-1)?.type||null;S.lastRecommended=S.history.slice().reverse().find(x=>(S.recommendationIds||[]).includes(x.type))?.type||null;save();historyView()}}
function clearHistory(){if(confirm("Tüm antrenman kayıtları silinsin mi?")){S.history=[];S.last=null;S.lastRecommended=null;save();historyView()}}

function analysis(){nav("navAnalysis");screen.innerHTML=`<div class="head"><div class="eyebrow">ANALİZ</div><h1>Vural'ın gelişimi</h1><p>Son 7, 15 veya 30 günde ne çalıştığını gör.</p></div><div class="ranges"><button class="on" onclick="renderA(7,this)">7 gün</button><button onclick="renderA(15,this)">15 gün</button><button onclick="renderA(30,this)">1 ay</button></div><div class="analysisTabs"><button class="on" onclick="renderA(7)">Analiz</button><button onclick="calendarView()">Takvim</button><button onclick="weightChart()">Ağırlık</button></div><div id="analysisBody"></div>`;renderA(7)}
function renderA(days,btn){
 document.querySelectorAll(".ranges button").forEach(x=>x.classList.remove("on"));
 if(btn)btn.classList.add("on");
 let d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-days+1);
 let hs=S.history.filter(x=>new Date(x.date)>=d),sets={},repsTotal=0,minutes=0,vol=0;
 hs.forEach(h=>{
   minutes+=Math.max(0,Math.round((h.duration||0)/60000));
   h.exercises.forEach(x=>{
     let e=ex(x.id),k=e.primary;sets[k]=(sets[k]||0)+x.reps.length;
     repsTotal+=x.reps.reduce((a,r)=>a+Number(r||0),0);
     vol+=x.reps.reduce((a,r)=>a+(Number(x.weight)||0)*Number(r||0),0);
   });
 });
 let max=Math.max(1,...Object.values(sets));
 let bars=Object.entries(sets).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="barRow"><span>${esc(k)}</span><div><i style="width:${v/max*100}%"></i></div><b>${v}</b></div>`).join("")||`<div class="emptyMini">Bu dönemde kayıt yok.</div>`;
 let avg=hs.length?Math.round(minutes/hs.length):0;
 let top=Object.entries(sets).sort((a,b)=>b[1]-a[1])[0]?.[0]||"—";
 let low=Object.entries(sets).sort((a,b)=>a[1]-b[1])[0]?.[0]||"—";
 let feedback=hs.length?`Son ${days} günde <b>${hs.length}</b> antrenman yaptın. En yüksek çalışma hacmi <b>${esc(top)}</b> bölgesinde. Dağılımı düzenli takip etmeye devam et.`:"Seçilen dönemde tamamlanmış antrenman yok.";
 screen.querySelector("#analysisBody").innerHTML=`
 <div class="summary"><div><span>Antrenman</span><b>${hs.length}</b></div><div><span>Toplam set</span><b>${Object.values(sets).reduce((a,b)=>a+b,0)}</b></div><div><span>Toplam tekrar</span><b>${repsTotal}</b></div></div>
 <div class="summary"><div><span>Toplam süre</span><b>${minutes} dk</b></div><div><span>Ortalama</span><b>${avg} dk</b></div><div><span>Hacim</span><b>${Math.round(vol).toLocaleString("tr-TR")} kg</b></div></div>
 <section class="card"><div class="section">KAS GRUBU DAĞILIMI</div>${bars}<p class="analysisHint">En çok: <b>${esc(top)}</b> · En az: <b>${esc(low)}</b></p></section>
 <section class="card"><div class="section">VURALPT GERİ BİLDİRİMİ</div><p>${feedback}</p></section>`;
}
v3Home();
/* V2.0 integrity helpers */
function v20Status(){
  const c=cycleInfo();
  return {
    version:"2.0",
    programs:c.sequence,
    lastCompleted:c.last,
    recommended:c.next,
    historyCount:S.history.length,
    customPrograms:Object.keys(S.programs).length
  };
}

function replaceExercise(oldId,newId){
 if(!builder.includes(oldId))return;
 let i=builder.indexOf(oldId);builder[i]=newId;
 if(builderConfig[oldId]){builderConfig[newId]={...builderConfig[oldId]};delete builderConfig[oldId]}
 builderView(window.builderCode);
}

function calendarView(){
 const now=new Date(), y=now.getFullYear(), m=now.getMonth();
 const first=new Date(y,m,1), last=new Date(y,m+1,0);
 const byDay={};S.history.forEach(h=>{let d=new Date(h.date);if(d.getFullYear()===y&&d.getMonth()===m)byDay[d.getDate()]=h});
 let html=`<div class="calendar"><div class="calTitle">${new Intl.DateTimeFormat("tr-TR",{month:"long",year:"numeric"}).format(now)}</div><div class="calGrid">${["P","S","Ç","P","C","C","P"].map(x=>`<b>${x}</b>`).join("")}`;
 let offset=(first.getDay()+6)%7; for(let i=0;i<offset;i++)html+=`<span class="emptyDay"></span>`;
 for(let d=1;d<=last.getDate();d++){let h=byDay[d];html+=`<button class="${h?'trained':'emptyDayBtn'}" onclick="${h?`logDetail(${S.history.indexOf(h)})`:"void(0)"}"><b>${d}</b>${h?`<small>${esc(prog(h.type)?.id||h.type)}</small>`:`<small>—</small>`}</button>`}
 html+=`</div><p class="calendarLegend">İşaretli günler tamamlanan antrenmanlardır. Boş günler kayıt olarak sayılmaz.</p></div>`;
 screen.querySelector("#analysisBody").innerHTML=html;
}
function weightChart(){
 let by={};
 S.history.forEach(h=>h.exercises.forEach(x=>{if(!by[x.id])by[x.id]=[];if(Number(x.weight)>0)by[x.id].push({d:x.weight,date:x.date})}));
 let items=Object.entries(by).filter(([id,a])=>a.length>=1).slice(0,12).map(([id,a])=>{let e=ex(id),first=a[0].d,last=a.at(-1).d,delta=last-first;return `<div class="change"><div><b>${esc(e.name)}</b><small>${first} kg → ${last} kg</small></div><strong>${delta>0?"+":""}${delta} kg</strong></div>`}).join("");
 screen.querySelector("#analysisBody").innerHTML=`<section class="card"><div class="section">AĞIRLIK GELİŞİMİ</div>${items||`<div class="emptyMini">Henüz yeterli ağırlık kaydı yok.</div>`}</section>`;
}

function toggleFavorite(id){
 if(!S.favorites)S.favorites=[];
 S.favorites=S.favorites.includes(id)?S.favorites.filter(x=>x!==id):[...S.favorites,id];
 save(); detail(id);
}

function ptFeedback(){
 const h=S.history||[], recent=h.slice(-3);
 if(!recent.length)return "Henüz yeterli antrenman verisi yok.";
 const count=recent.length;
 const mins=Math.round(recent.reduce((a,x)=>a+(x.duration||0),0)/60000);
 return `Son ${count} antrenmanda toplam yaklaşık ${mins} dakika çalıştın. Programını düzenli kayıtla takip etmeye devam et.`;
}
function recoveryHint(){
 const last=S.history.at(-1); if(!last)return "Henüz toparlanma verisi yok.";
 const days=Math.floor((Date.now()-new Date(last.date).getTime())/86400000);
 return days<1?"Son antrenman bugün tamamlandı. Aynı kas gruplarını yeniden yüklemeden önce toparlanmayı göz önünde bulundur.":`Son antrenmandan bu yana ${days} gün geçti.`;
}
function healthCheck(ids){
 const groups=ids.map(id=>ex(id)?.primary).filter(Boolean);
 const counts={};groups.forEach(g=>counts[g]=(counts[g]||0)+1);
 return Object.entries(counts).filter(([,n])=>n>=4).map(([g,n])=>`${g} bölgesinde ${n} hareket seçildi`).join(" · ");
}

function migrateV2(){
 if(!S.progression)S.progression={};
 if(!S.favorites)S.favorites=[];
 if(!Array.isArray(S.recommendationIds)||!S.recommendationIds.length)S.recommendationIds=["A","B"];
 if(!("lastRecommended" in S))S.lastRecommended=(S.recommendationIds.includes(S.last)?S.last:null);
 Object.keys(S.weights||{}).forEach(id=>{if(!S.progression[id])S.progression[id]={weight:S.weights[id],successful:0,pending:false}});
 save();
}

function demoMode(){
 const now=Date.now();
 S.history=[
  {date:new Date(now-5*86400000).toISOString(),type:"A",duration:48*60000,exercises:seed.A.exerciseIds.map(id=>({id,reps:[10,10,10],weight:S.weights[id]||10,success:true}))},
  {date:new Date(now-3*86400000).toISOString(),type:"B",duration:52*60000,exercises:seed.B.exerciseIds.map(id=>({id,reps:[10,10,10],weight:S.weights[id]||10,success:true}))}
 ];
 S.last="B";S.lastRecommended="B";save();home();
}
function clearDemo(){S.history=[];S.last=null;S.lastRecommended=null;save();home();}
